inline bool VerifyDTTBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<DTT>(DTTIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedDTTBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<DTT>(DTTIdentifier());
}

inline void FinishDTTBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<DTT> root) {
  fbb.Finish(root, DTTIdentifier());
}

inline void FinishSizePrefixedDTTBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<DTT> root) {
  fbb.FinishSizePrefixed(root, DTTIdentifier());
}

inline std::unique_ptr<DTTT> UnPackDTT(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<DTTT>(GetDTT(buf)->UnPack(res));
}

inline std::unique_ptr<DTTT> UnPackSizePrefixedDTT(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<DTTT>(GetSizePrefixedDTT(buf)->UnPack(res));
}

#endif  // FLATBUFFERS_GENERATED_DTT_MAIN_H_
